template:
trait Draw {
    fn draw(&self) -> String;
}

struct Circle;
struct Square;

impl Draw for Circle {
    fn draw(&self) -> String {
        String::from("o")
    }
}

impl Draw for Square {
    fn draw(&self) -> String {
        String::from("□")
    }
}

fn shapes() -> Vec<⟦elem_ty⟧> {
    vec![⟦first_elem⟧, Box::new(Square)]
}

fn main() {
    for s in shapes() {
        print!("{}", s.draw());
    }
    println!();
}

tests:
#[test]
fn draws_both() {
    let all: String = shapes().iter().map(|s| s.draw()).collect();
    assert_eq!(all, "o□");
}
